// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./Token/LP_Token.sol";
import "./interfaces/IERC20.sol";

contract DexPair {
    address public token0;
    address public token1;
    LPToken public lpToken;

    uint112 private reserve0;
    uint112 private reserve1;

    bool private initialized = false;

    event Mint(address indexed provider, uint amount0, uint amount1, uint liquidity);
    event Burn(address indexed provider, uint amount0, uint amount1, uint liquidity);
    event Swap(address indexed sender, uint amountIn, uint amountOut);

    // initialize called by factory right after creation
    function initialize(address _token0, address _token1) external {
        require(!initialized, "Already initialized");
        require(_token0 != address(0) && _token1 != address(0), "Zero address");
        require(_token0 != _token1, "Identical tokens");

        token0 = _token0;
        token1 = _token1;

        // deploy LP token; msg.sender is this DexPair (because factory used `new DexPair()` and then called initialize,
        // however LPToken's constructor sets pairContract = msg.sender, so call must be from the pair itself.
        // Because we are inside the pair contract, msg.sender here is Factory; to ensure LPToken pairContract is pair,
        // we deploy LPToken from this contract (msg.sender for LPToken constructor will be this contract)
        lpToken = new LPToken("LP Token", "LPT");

        initialized = true;
    }

    // get reserves
    function getReserves() public view returns (uint112, uint112) {
        return (reserve0, reserve1);
    }

    // Add liquidity -> returns liquidity minted
    function addLiquidity(uint amount0, uint amount1) external returns (uint liquidity) {
        require(initialized, "Not initialized");
        require(amount0 > 0 && amount1 > 0, "Invalid amounts");

        IERC20(token0).transferFrom(msg.sender, address(this), amount0);
        IERC20(token1).transferFrom(msg.sender, address(this), amount1);

        (uint112 _r0, uint112 _r1) = getReserves();

        if (_r0 == 0 && _r1 == 0) {
            // initial liquidity: mint sqrt(amount0 * amount1)
            liquidity = sqrt(amount0 * amount1);
        } else {
            // proportional liquidity based on existing supply
            uint _totalSupply = lpToken.totalSupply();
            require(_totalSupply > 0, "No total supply");
            uint liquidity0 = (amount0 * _totalSupply) / _r0;
            uint liquidity1 = (amount1 * _totalSupply) / _r1;
            liquidity = min(liquidity0, liquidity1);
        }

        require(liquidity > 0, "Insufficient liquidity");

        // mint LP to provider
        lpToken._mint(msg.sender, liquidity);

        // update reserves
        reserve0 = uint112(uint(_r0) + amount0);
        reserve1 = uint112(uint(_r1) + amount1);

        emit Mint(msg.sender, amount0, amount1, liquidity);
    }

    // Remove liquidity -> returns amounts
    function removeLiquidity(uint liquidity) external returns (uint amount0, uint amount1) {
        require(initialized, "Not initialized");
        require(liquidity > 0, "Invalid liquidity");

        uint _totalSupply = lpToken.totalSupply();
        require(_totalSupply > 0, "No supply");

        (uint112 _r0, uint112 _r1) = getReserves();

        amount0 = (liquidity * _r0) / _totalSupply;
        amount1 = (liquidity * _r1) / _totalSupply;

        // burn LP tokens from caller
        lpToken._burn(msg.sender, liquidity);

        // update reserves
        reserve0 = uint112(uint(_r0) - amount0);
        reserve1 = uint112(uint(_r1) - amount1);

        // transfer underlying tokens back to provider
        IERC20(token0).transfer(msg.sender, amount0);
        IERC20(token1).transfer(msg.sender, amount1);

        emit Burn(msg.sender, amount0, amount1, liquidity);
    }

    // Swap: returns amountOut
    function swap(uint amountIn, address tokenIn) external returns (uint amountOut) {
        require(initialized, "Not initialized");
        require(amountIn > 0, "Invalid input");
        require(tokenIn == token0 || tokenIn == token1, "Invalid token");

        bool isToken0 = tokenIn == token0;
        (uint112 r0, uint112 r1) = getReserves();

        if (isToken0) {
            amountOut = getAmountOut(amountIn, uint(r0), uint(r1));
            IERC20(token0).transferFrom(msg.sender, address(this), amountIn);
            IERC20(token1).transfer(msg.sender, amountOut);

            // update reserves
            reserve0 = uint112(uint(r0) + amountIn);
            reserve1 = uint112(uint(r1) - amountOut);
        } else {
            amountOut = getAmountOut(amountIn, uint(r1), uint(r0));
            IERC20(token1).transferFrom(msg.sender, address(this), amountIn);
            IERC20(token0).transfer(msg.sender, amountOut);

            reserve1 = uint112(uint(r1) + amountIn);
            reserve0 = uint112(uint(r0) - amountOut);
        }

        emit Swap(msg.sender, amountIn, amountOut);
    }

    // constant product formula with 0.3% fee (like Uniswap)
    function getAmountOut(uint amountIn, uint reserveIn, uint reserveOut) public pure returns (uint) {
        require(reserveIn > 0 && reserveOut > 0, "Insufficient liquidity");
        uint amountInWithFee = amountIn * 997; // fee 0.3%
        uint numerator = amountInWithFee * reserveOut;
        uint denominator = (reserveIn * 1000) + amountInWithFee;
        return numerator / denominator;
    }

    // helpers
    function min(uint x, uint y) private pure returns (uint) {
        return x < y ? x : y;
    }

    function sqrt(uint y) private pure returns (uint z) {
        if (y > 3) {
            z = y;
            uint x = y / 2 + 1;
            while (x < z) {
                z = x;
                x = (y / x + x) / 2;
            }
        } else if (y != 0) {
            z = 1;
        }
    }
}

