// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./DexFactory.sol";
import "./DexPair.sol";

contract DexRouter {
    DexFactory public factory;

    constructor(address _factory) {
        factory = DexFactory(_factory);
    }

    // Add Liquidity - returns liquidity minted
    function addLiquidity(address tokenA, address tokenB, uint amountA, uint amountB)
        external returns (uint liquidity)
    {
        address pair = factory.getPair(tokenA, tokenB);

        if (pair == address(0)) {
            pair = factory.createPair(tokenA, tokenB);
        }

        // call pair.addLiquidity which returns a single uint
        liquidity = DexPair(pair).addLiquidity(amountA, amountB);
    }

    // Swap
    function swap(address tokenIn, address tokenOut, uint amountIn)
        external returns (uint amountOut)
    {
        address pair = factory.getPair(tokenIn, tokenOut);
        require(pair != address(0), "Pair doesn't exist");

        amountOut = DexPair(pair).swap(amountIn, tokenIn);
    }
}

